class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        grid = [row[:] for row in grid]
        N = m * n
        TOP = N

        parent = list(range(N + 1))
        size = [0] * (N + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        record = []
        for r, c in hits:
            if grid[r][c] == 1:
                grid[r][c] = 0
                record.append(1)
            else:
                record.append(0)

        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    size[r * n + c] = 1

        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    idx = r * n + c
                    if r == 0:
                        union(idx, TOP)
                    if r + 1 < m and grid[r + 1][c] == 1:
                        union(idx, (r + 1) * n + c)
                    if c + 1 < n and grid[r][c + 1] == 1:
                        union(idx, r * n + c + 1)

        ans = [0] * len(hits)

        for i in range(len(hits) - 1, -1, -1):
            if record[i] == 0:
                continue

            r, c = hits[i]
            before = size[find(TOP)]

            idx = r * n + c
            size[idx] = 1
            grid[r][c] = 1

            if r == 0:
                union(idx, TOP)
            if r > 0 and grid[r - 1][c] == 1:
                union(idx, (r - 1) * n + c)
            if r + 1 < m and grid[r + 1][c] == 1:
                union(idx, (r + 1) * n + c)
            if c > 0 and grid[r][c - 1] == 1:
                union(idx, r * n + c - 1)
            if c + 1 < n and grid[r][c + 1] == 1:
                union(idx, r * n + c + 1)

            after = size[find(TOP)]
            ans[i] = max(0, after - before - 1)

        return ans
```

