from typing import List

class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {}

        for v in arr:
            dp[v] = 1
            for a in arr:
                if a >= v:
                    break
                if v % a == 0:
                    b = v // a
                    if b in dp:
                        dp[v] = (dp[v] + dp[a] * dp[b]) % MOD

        return sum(dp.values()) % MOD
```

