from typing import List

class Solution:
    def canCross(self, stones: List[int]) -> bool:
        if len(stones) < 2:
            return False
        if stones[1] != 1:
            return False

        stone_set = set(stones)
        last = stones[-1]
        dp = {0: {0}}

        for pos in stones:
            if pos not in dp:
                continue
            for k in dp[pos]:
                for step in (k - 1, k, k + 1):
                    if step > 0:
                        nxt = pos + step
                        if nxt in stone_set:
                            dp.setdefault(nxt, set()).add(step)

        return last in dp
