from typing import List
from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        m = len(nums)
        full = (1 << m) - 1
        dp = [-1] * (1 << m)
        dp[0] = 0

        for mask in range(1 << m):
            if dp[mask] == -1:
                continue

            used = mask.bit_count()
            if used == m:
                continue

            op = used // 2 + 1

            for i in range(m):
                if mask & (1 << i):
                    continue
                for j in range(i + 1, m):
                    if mask & (1 << j):
                        continue

                    new_mask = mask | (1 << i) | (1 << j)
                    score = dp[mask] + op * gcd(nums[i], nums[j])

                    if score > dp[new_mask]:
                        dp[new_mask] = score

        return dp[full]
```

