class Solution:
    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        m = 3 ** numSlots
        dp = [-1] * m
        dp[0] = 0

        pow3 = [1] * numSlots
        for i in range(1, numSlots):
            pow3[i] = pow3[i - 1] * 3

        for x in nums:
            ndp = [-1] * m
            for mask, cur in enumerate(dp):
                if cur < 0:
                    continue

                for slot in range(numSlots):
                    if (mask // pow3[slot]) % 3 < 2:
                        nmask = mask + pow3[slot]
                        val = cur + (x & (slot + 1))
                        if val > ndp[nmask]:
                            ndp[nmask] = val

            dp = ndp

