from typing import List

class Solution:
    def maxTotalFruits(self, fruits: List[List[int]], startPos: int, k: int) -> int:
        n = len(fruits)
        ans = 0
        cur = 0
        left = 0

        for right in range(n):
            cur += fruits[right][1]

            while left <= right:
                lpos = fruits[left][0]
                rpos = fruits[right][0]

                if startPos <= lpos:
                    steps = rpos - startPos
                elif startPos >= rpos:
                    steps = startPos - lpos
                else:
                    steps = (rpos - lpos) + min(startPos - lpos, rpos - startPos)

                if steps <= k:
                    break

                cur -= fruits[left][1]
                left += 1

            if left <= right:
                ans = max(ans, cur)

        return ans
