    def maxRunTime(self, n: int, batteries: List[int]) -> int:
        lo, hi = 0, sum(batteries) // n

        while lo < hi:
            mid = (lo + hi + 1) // 2
            total = 0
            needed = n * mid

            for b in batteries:
                total += min(b, mid)
                if total >= needed:
                    break

            if total >= needed:
                lo = mid
            else:
                hi = mid - 1

        return lo
