        m, n = len(grid), len(grid[0])

        row_pref = [[0] * (n + 1) for _ in range(m)]
        for i in range(m):
            for j in range(n):
                row_pref[i][j + 1] = row_pref[i][j] + grid[i][j]

        col_pref = [[0] * n for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                col_pref[i + 1][j] = col_pref[i][j] + grid[i][j]

        for k in range(min(m, n), 1, -1):
            for i in range(m - k + 1):
                for j in range(n - k + 1):
                    target = row_pref[i][j + k] - row_pref[i][j]

                    ok = True
                    for r in range(i, i + k):
                        if row_pref[r][j + k] - row_pref[r][j] != target:
                            ok = False
                            break
                    if not ok:
                        continue

                    for c in range(j, j + k):
                        if col_pref[i + k][c] - col_pref[i][c] != target:
                            ok = False
                            break
                    if not ok:
                        continue

                    diag1 = diag2 = 0
                    for t in range(k):
                        diag1 += grid[i + t][j + t]
                        diag2 += grid[i + t][j + k - 1 - t]

                    if diag1 == target and diag2 == target:
                        return k

        return 1
