from typing import List
from bisect import bisect_left

class Solution:
    def maximumBeauty(self, flowers: List[int], newFlowers: int, target: int, full: int, partial: int) -> int:
        n = len(flowers)
        b = sorted(x for x in flowers if x < target)
        m = len(b)
        comp0 = n - m

        if m == 0:
            return n * full

        pref = [0] * (m + 1)
        for i, v in enumerate(b):
            pref[i + 1] = pref[i] + v

        ans = 0
        cost_complete = 0

        for k in range(m + 1):
            if k > 0:
                cost_complete += target - b[m - k]
            if cost_complete > newFlowers:
                break

            rem = newFlowers - cost_complete
            p = m - k

            if p == 0:
                beauty = (comp0 + k) * full
                if beauty > ans:
                    ans = beauty
                continue

            lo, hi = 0, target - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                q = bisect_left(b, mid, 0, p)
                cost = q * mid - pref[q]
                if cost <= rem:
                    lo = mid
                else:
                    hi = mid - 1

            L = lo
            beauty = (comp0 + k) * full + L * partial
            if beauty > ans:
                ans = beauty

        return ans
```

