class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        best_node = min(initial)
        best_count = n + 1

        for removed in initial:
            visited = [False] * n
            q = deque()

            for node in initial:
                if node != removed and not visited[node]:
                    visited[node] = True
                    q.append(node)

            while q:
                u = q.popleft()
                for v in range(n):
                    if graph[u][v] == 1 and v != removed and not visited[v]:
                        visited[v] = True
                        q.append(v)

            count = sum(visited)

            if count < best_count or (count == best_count and removed < best_node):
                best_count = count
                best_node = removed

        return best_node
