class Solution:
    def maxCompatibilitySum(self, students: List[List[int]], mentors: List[List[int]]) -> int:
        m = len(students)
        n = len(students[0])

        score = [[0] * m for _ in range(m)]
        for i in range(m):
            for j in range(m):
                for k in range(n):
                    if students[i][k] == mentors[j][k]:
                        score[i][j] += 1

        dp = [-1] * (1 << m)
        dp[0] = 0

        for mask in range(1 << m):
            if dp[mask] == -1:
                continue

            student = mask.bit_count()
            if student == m:
                continue

            for mentor in range(m):
                if not (mask & (1 << mentor)):
                    next_mask = mask | (1 << mentor)
                    dp[next_mask] = max(dp[next_mask], dp[mask] + score[student][mentor])

