from typing import List

class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        vals = sorted(set(nums))
        index = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)
        bit = [0] * (m + 1)

        def add(i: int, delta: int) -> None:
            while i <= m:
                bit[i] += delta
                i += i & -i

        def kth(k: int) -> int:
            idx = 0
            step = 1 << (m.bit_length() - 1)
            while step:
                nxt = idx + step
                if nxt <= m and bit[nxt] < k:
                    idx = nxt
                    k -= bit[nxt]
                step >>= 1
            return vals[idx]

        ans = []

        for i, x in enumerate(nums):
            add(index[x], 1)

            if i >= k:
                add(index[nums[i - k]], -1)

            if i >= k - 1:
                if k % 2 == 1:
                    ans.append(float(kth(k // 2 + 1)))
                else:
                    a = kth(k // 2)
                    b = kth(k // 2 + 1)
                    ans.append((a + b) / 2.0)

        return ans
