from typing import List
from functools import lru_cache

class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        @lru_cache(None)
        def dfs(n: int, a: int, b: int):
            if a + b == n + 1:
                return (1, 1)

            fixed = []
            flexible = []

            for i in range(1, n // 2 + 1):
                j = n + 1 - i
                if i == a or j == a:
                    fixed.append(a)
                elif i == b or j == b:
                    fixed.append(b)
                else:
                    flexible.append((i, j))

            if n % 2:
                fixed.append(n // 2 + 1)

            best_min = 10**9
            best_max = -1
            m = len(flexible)

            for mask in range(1 << m):
                survivors = fixed[:]
                for idx in range(m):
                    i, j = flexible[idx]
                    if (mask >> idx) & 1:
                        survivors.append(i)
                    else:
                        survivors.append(j)

                survivors.sort()
                na = survivors.index(a) + 1
                nb = survivors.index(b) + 1

                mn, mx = dfs(len(survivors), na, nb)
                best_min = min(best_min, mn + 1)
                best_max = max(best_max, mx + 1)

            return (best_min, best_max)

        earliest, latest = dfs(n, firstPlayer, secondPlayer)
        return [earliest, latest]
