class Solution:
    def spiralMatrixIII(self, rows: int, cols: int, rStart: int, cStart: int) -> List[List[int]]:
        total = rows * cols
        result = []

        r, c = rStart, cStart
        if 0 <= r < rows and 0 <= c < cols:
            result.append([r, c])

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        d = 0
        step = 1

        while len(result) < total:
            for _ in range(2):
                dr, dc = directions[d % 4]
                for _ in range(step):
                    r += dr
                    c += dc
                    if 0 <= r < rows and 0 <= c < cols:
                        result.append([r, c])
                        if len(result) == total:
                            return result
                d += 1
            step += 1

        return result
