from typing import List

class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        # At most 10 distinct characters
        if len(set(''.join(words) + result)) > 10:
            return False

        rev_words = [w[::-1] for w in words]
        rev_res = result[::-1]
        n = max([len(rev_res)] + [len(w) for w in rev_words])

        # Precompute column information
        col_words = [[] for _ in range(n)]
        col_unique = [[] for _ in range(n)]
        for pos in range(n):
            seen = set()
            for w in rev_words:
                if pos < len(w):
                    idx = ord(w[pos]) - 65
                    col_words[pos].append(idx)
                    seen.add(idx)
            col_unique[pos] = list(seen)

        res_col = [
            ord(rev_res[pos]) - 65 if pos < len(rev_res) else -1
            for pos in range(n)
        ]

        leading = [False] * 26
        for w in words:
            leading[ord(w[0]) - 65] = True
        leading[ord(result[0]) - 65] = True

        assigned = [-1] * 26
        used = [False] * 10

        def dfs(pos: int, carry: int) -> bool:
            if pos == n:
                return carry == 0

            chars_col = [idx for idx in col_unique[pos] if assigned[idx] == -1]
            res_idx = res_col[pos]

            def assign(i: int) -> bool:
                if i == len(chars_col):
                    total = carry
                    for idx in col_words[pos]:
                        total += assigned[idx]

                    digit = total % 10
                    carry_out = total // 10

                    if res_idx == -1:
                        if digit != 0:
                            return False
                        return dfs(pos + 1, carry_out)

                    if assigned[res_idx] != -1:
                        if assigned[res_idx] != digit:
                            return False
                        return dfs(pos + 1, carry_out)

                    if used[digit]:
                        return False
                    if digit == 0 and leading[res_idx]:
                        return False

                    assigned[res_idx] = digit
                    used[digit] = True
                    ok = dfs(pos + 1, carry_out)
                    used[digit] = False
                    assigned[res_idx] = -1
                    return ok

                idx = chars_col[i]
                for d in range(10):
                    if not used[d]:
                        if d == 0 and leading[idx]:
                            continue
                        used[d] = True
                        assigned[idx] = d
                        if assign(i + 1):
                            return True
                        assigned[idx] = -1
                        used[d] = False
                return False

            return assign(0)

        return dfs(0, 0)
